const updateMergedStock = `-- name: UpdateMergedStock :exec
UPDATE stocks
SET shares = $2, buy_price = $3, buy_date = $4, notes = $5, category = $6, updated_at = $7
WHERE id = $1
`

type UpdateMergedStockParams struct {
	ID        uuid.UUID
	Shares    float64
	BuyPrice  float64
	BuyDate   time.Time
	Notes     *string
	Category  AssetCategory
	UpdatedAt *time.Time
}

func (q *Queries) UpdateMergedStock(ctx context.Context, arg UpdateMergedStockParams) error {
	_, err := q.db.Exec(ctx, updateMergedStock,
		arg.ID,
		arg.Shares,
		arg.BuyPrice,
		arg.BuyDate,
		arg.Notes,
		arg.Category,
		arg.UpdatedAt,
	)
	return err
}
